import os, pty, sys, select, time, signal, termios, tty, fcntl, struct, array

def main():
    cmd = sys.argv[1]
    args = sys.argv[2:]
    keys_list = os.environ.get('KEYS', '').split('|')
    # each item is a single string (bytes)

    pid, fd = pty.fork()
    if pid == 0:
        # child - set terminal size
        os.execvp(cmd, [cmd] + args)

    rows = int(os.environ.get('ROWS', '30'))
    cols = int(os.environ.get('COLS', '80'))
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))

    out = open(os.environ.get('OUTFILE', '/tmp/walktest/out.log'), 'wb')

    key_idx = 0
    deadline = time.time() + float(os.environ.get('WAIT', '5'))
    last_activity = time.time()
    has_bgquery = False
    has_cursquery = False
    buf = b''
    key_delay = float(os.environ.get('KEYDELAY', '0.5'))
    quit_delay = float(os.environ.get('QUIT_DELAY', '0.8'))
    initial_delay = float(os.environ.get('INITIAL_DELAY', '0.5'))
    sent_initial = False

    while True:
        if time.time() > deadline:
            break
        r, _, _ = select.select([fd], [], [], 0.05)
        if fd in r:
            try:
                data = os.read(fd, 4096)
            except OSError:
                break
            if not data:
                break
            out.write(data)
            out.flush()
            buf += data
            if not has_bgquery and b']11;?' in buf:
                os.write(fd, b'\x1b]11;rgb:0000/0000/0000\x1b\\')
                has_bgquery = True
            if not has_cursquery and b'[6n' in buf:
                os.write(fd, b'\x1b[1;1R')
                has_cursquery = True
            last_activity = time.time()
        else:
            if not sent_initial and time.time() > last_activity + initial_delay:
                sent_initial = True
                last_activity = time.time()
            elif sent_initial and key_idx < len(keys_list):
                if keys_list[key_idx] == '':
                    key_idx += 1
                    continue
                if time.time() > last_activity + key_delay:
                    # parse escape sequences in key string
                    k = keys_list[key_idx]
                    if k.startswith('\\x'):
                        b = bytes.fromhex(k[2:])
                    elif k == 'UP':
                        b = b'\x1b[A'
                    elif k == 'DOWN':
                        b = b'\x1b[B'
                    elif k == 'LEFT':
                        b = b'\x1b[D'
                    elif k == 'RIGHT':
                        b = b'\x1b[C'
                    elif k == 'ENTER':
                        b = b'\r'
                    elif k == 'BACKSPACE':
                        b = b'\x7f'
                    elif k == 'SPACE':
                        b = b' '
                    elif k == 'ESC':
                        b = b'\x1b'
                    elif k == 'CTRLC':
                        b = b'\x03'
                    elif k == 'TAB':
                        b = b'\t'
                    else:
                        b = k.encode()
                    os.write(fd, b)
                    key_idx += 1
                    last_activity = time.time()
            elif key_idx >= len(keys_list) and time.time() > last_activity + quit_delay:
                try:
                    os.kill(pid, signal.SIGTERM)
                except:
                    pass
                time.sleep(0.2)
                break

    try:
        os.waitpid(pid, 0)
    except OSError:
        pass
