package main

import (
	"bytes"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"syscall"
)

type app struct {
	opts *Options

	cwd     string
	entries []os.DirEntry // filtered entries
	cursor  int

	rows, cols int

	tty     *os.File
	restore func()

	out io.Writer // output to terminal (tty)

	// Buffer of previously rendered lines so we can redraw diffs
	prevLines []string

	quit     bool
	cancel   bool // true if Ctrl+C
	hidden   bool // show hidden files
	preview  bool
	withBorder bool
	help     bool
}

func run(opts *Options) error {
	// Resolve path
	var startPath string
	if opts.Path == "" {
		wd, err := os.Getwd()
		if err != nil {
			return err
		}
		startPath = wd
	} else {
		if filepath.IsAbs(opts.Path) {
			startPath = opts.Path
		} else {
			wd, err := os.Getwd()
			if err != nil {
				return err
			}
			startPath = filepath.Join(wd, opts.Path)
		}
	}

	// Open /dev/tty for I/O, panicking in the way the original does.
	tty, err := openTTY()
	if err != nil {
		panic(fmt.Sprintf("could not open a new TTY: %v", err))
	}

	a := &app{
		opts:       opts,
		cwd:        startPath,
		tty:        tty,
		out:        tty,
		hidden:     !opts.HideHidden,
		preview:    opts.Preview,
		withBorder: opts.WithBorder,
	}

	// Switch to raw mode
	restore, err := rawMode(int(tty.Fd()))
	if err != nil {
		return err
	}
	a.restore = restore

	// Handle signals
	cleanup := func() {
		// Clear line, show cursor, reset modes
		fmt.Fprint(a.out, "\r\x1b[2K")
		fmt.Fprint(a.out, "\x1b[?2004l\x1b[?25h\x1b[?1002l\x1b[?1003l\x1b[?1006l")
		a.restore()
		a.tty.Close()
	}

	defer cleanup()

	// Query terminal size
	if r, c, err := getSize(int(tty.Fd())); err == nil {
		a.rows, a.cols = r, c
	} else {
		a.rows, a.cols = 24, 80
	}

	// Initial setup output
	fmt.Fprint(a.out, "\x1b[?25l\x1b[?2004h")

	// Read entries
	if err := a.loadEntries(); err != nil {
		// Show error
	}

	// Render initial
	a.render(false)

	// Event loop
	buf := make([]byte, 32)
	for !a.quit {
		n, err := syscall.Read(int(tty.Fd()), buf)
		if err != nil {
			if err == syscall.EINTR {
				continue
			}
			break
		}
		if n <= 0 {
			break
		}
		a.handleInput(buf[:n])
		if !a.quit {
			a.render(false)
		}
	}

	// Clear rendered content before exit
	a.clearRendered()

	// On normal exit, print cwd (or selected dir) to stdout
	if !a.cancel {
		fmt.Println(a.cwd)
	}
	return nil
}

func (a *app) loadEntries() error {
	a.entries = nil
	entries, err := os.ReadDir(a.cwd)
	if err != nil {
		return err
	}
	for _, e := range entries {
		name := e.Name()
		if strings.HasPrefix(name, ".") && !a.hidden {
			continue
		}
		if a.opts.DirOnly && !e.IsDir() {
			continue
		}
		a.entries = append(a.entries, e)
	}
	sort.Slice(a.entries, func(i, j int) bool {
		return strings.ToLower(a.entries[i].Name()) < strings.ToLower(a.entries[j].Name())
	})
	if a.cursor >= len(a.entries) {
		a.cursor = len(a.entries) - 1
	}
	if a.cursor < 0 {
		a.cursor = 0
	}
	return nil
}

func (a *app) handleInput(data []byte) {
	s := string(data)
	// Simple key detection
	switch s {
	case "\x03": // Ctrl+C
		a.cancel = true
		a.quit = true
		return
	case "\x1b", "q":
		a.quit = true
		return
	case "\r", "\n":
		a.enterDir()
		return
	case "\x7f", "\x08":
		a.exitDir()
		return
	case " ":
		a.preview = !a.preview
		return
	case ".":
		a.hidden = !a.hidden
		a.cursor = 0
		a.loadEntries()
		return
	case "?":
		a.help = !a.help
		return
	}
	// Arrow keys
	if strings.HasPrefix(s, "\x1b[") || strings.HasPrefix(s, "\x1bO") {
		switch s {
		case "\x1b[A", "\x1bOA":
			a.moveCursor(0, -1)
		case "\x1b[B", "\x1bOB":
			a.moveCursor(0, 1)
		case "\x1b[C", "\x1bOC":
			a.moveCursor(1, 0)
		case "\x1b[D", "\x1bOD":
			a.moveCursor(-1, 0)
		case "\x1b[1;2A", "\x1b[a":
			a.cursor = 0
		case "\x1b[1;2B", "\x1b[b":
			a.cursor = len(a.entries) - 1
			if a.cursor < 0 {
				a.cursor = 0
			}
		}
		return
	}
	// Single char keys
	switch s {
	case "h":
		a.moveCursor(-1, 0)
	case "l":
		a.moveCursor(1, 0)
	case "j":
		a.moveCursor(0, 1)
	case "k":
		a.moveCursor(0, -1)
	}
}

func (a *app) enterDir() {
	if len(a.entries) == 0 {
		return
	}
	e := a.entries[a.cursor]
	if !e.IsDir() {
		return
	}
	a.cwd = filepath.Join(a.cwd, e.Name())
	a.cursor = 0
	a.loadEntries()
}

func (a *app) exitDir() {
	parent := filepath.Dir(a.cwd)
	if parent == a.cwd {
		return
	}
	a.cwd = parent
	a.cursor = 0
	a.loadEntries()
}

// layout computes the grid layout: returns rows, cols, colWidth
func (a *app) layout() (rows, cols, colWidth int) {
	n := len(a.entries)
	if n == 0 {
		return 0, 1, 0
	}
	// Find max width
	maxW := 0
	for _, e := range a.entries {
		w := len(e.Name())
		if e.IsDir() {
			w++
		}
		if w > maxW {
			maxW = w
		}
	}
	// Column gap = 4 spaces
	gap := 4
	availWidth := a.cols
	if availWidth < 1 {
		availWidth = 80
	}
	// Available height: leave some rows for header + margin
	maxRows := a.rows - 2
	if maxRows < 1 {
		maxRows = 1
	}
	// Also, the walk appears to cap at maxRows ~10
	if maxRows > 10 {
		maxRows = 10
	}
	// Start with minimum columns, then figure out column count
	// cols = ceil(n / maxRows)
	cols = (n + maxRows - 1) / maxRows
	if cols < 1 {
		cols = 1
	}
	// Ensure fits in width
	for cols > 1 && cols*maxW+(cols-1)*gap > availWidth {
		cols--
	}
	rows = (n + cols - 1) / cols
	colWidth = maxW
	return
}

func (a *app) moveCursor(dx, dy int) {
	rows, cols, _ := a.layout()
	if rows == 0 {
		return
	}
