	for i, line := range lines {
		buf.WriteString("\r")
		buf.WriteString(line)
		buf.WriteString("\x1b[K")
		if i < len(lines)-1 {
			buf.WriteString("\n")
		}
	}
	// Clear lines that existed previously but don't anymore
	prev := a.prevLines
	if len(prev) > len(lines) {
		for i := len(lines); i < len(prev); i++ {
			buf.WriteString("\n\r\x1b[2K")
		}
	}
	// Move back to top, col 1
	totalLines := len(lines)
	if len(prev) > totalLines {
		totalLines = len(prev)
	}
	if totalLines > 1 {
		buf.WriteString(fmt.Sprintf("\x1b[%dA", totalLines-1))
	}
	buf.WriteString("\r")

